class Solution {
  public int countValidSubarrays(int[] nums, int x) {
    int n = nums.length, count = 0;
    for (int l = 0; l < n; l++) {
      long sum = 0;
      for (int r = l; r < n; r++) {
        sum += nums[r];
        if (sum % 10 != x) continue;
        long first = sum;
        while (first >= 10) first /= 10;
        if (first == x) count++;
      }
    }
    return count;
  }
}
